// Initialize the message history array if it doesn't exist
let history = context.get('msgHistory') || [];

// Get the current time in milliseconds
const now = Date.now();

if (!msg.stat) {
    // Add the current message timestamp to the history
    history.push(now);
}

// Define our time windows (in milliseconds)
const oneMin = 60 * 1000;
const fifteenMin = 15 * 60 * 1000;
const oneHour = 60 * 60 * 1000;

// 1. Remove timestamps older than one hour to keep the array lean
history = history.filter(ts => (now - ts) < oneHour);

// 2. Count messages in each window
const count1m = history.filter(ts => (now - ts) < oneMin).length;
const count15m = history.filter(ts => (now - ts) < fifteenMin).length;
const count1h = history.length; // Already filtered to 1 hour

// Save the updated history back to context
context.set('msgHistory', history);

// Prepare the output message
msg.payload = {
    lastMinute: count1m,
    last15Minutes: count15m,
    lastHour: count1h
};

if (msg.stat) {
    if (msg.statx === "1m") {
        return [null, { topic: "1 minute", payload: msg.payload.lastMinute }, null, null];
    }
    if (msg.statx === "15m") {
        return [null, null, { topic: "15 minutes", payload: msg.payload.last15Minutes }, null];
    }
    if (msg.statx === "1h") {
        return [null, null, null, { topic: "1 hour", payload: msg.payload.lastHour }, null];
    }
} else {
    return [msg, null, null, null];
}

let state = context.get("state") || false;

if (msg.switch) {
    state = msg.payload;
    context.set("state", state);
    if (state) {
        node.status({ fill: "green", shape: "ring", text: "On" });
    } else {
        node.status({ fill: "grey", shape: "ring", text: "Off" });
    }
    return;
}

if (state) {
    return msg;
}

let path = context.get("path");
let topic = context.get("topic");
let count = context.get("count") || 0;

// incoming message is a new payload filter
if (msg.topic === "__path") {
    path = msg.payload;
    if (path === "") {
        path = undefined;
        context.set("path");
    } else {
        context.set("path", path);
    }
    context.set("count");
    return [{topic:"reset", payload: []}]; // reset the chart
}

// incoming message is a new topic filter
if (msg.topic === "__topic") {
    topic = msg.payload;
    if (topic === "") {
        topic = undefined;
        context.set("topic");
    } else {
        context.set("topic", topic);
    }
    context.set("count");
    return [{ topic: "reset", payload: [] }]; // reset the chart
}

if ((path === undefined) || (topic === undefined)) {
    node.status({ fill: "grey", shape: "ring", text: "No filter specified" });
    return;
}

if (count === 0) {
    node.status({ fill: "yellow", shape: "ring", text: "Waiting for message..." });
} else {
    node.status({ fill: "green", shape: "ring", text: count + " messages" });
}

/**
 * Helper to get nested property
 * @param {Object} obj - The object to search
 * @param {string} path - The path string (e.g. "a.b.c")
 */
function getNestedValue(obj, path) {
    return path.split('.').reduce((acc, part) => {
        return (acc && acc[part] !== undefined) ? acc[part] : undefined;
    }, obj);
}

if (topic !== "*") {
    if (msg.topic !== topic) {
        // there is a topic filter, but it does not match, ignore
        return null;
    } 
}
if (path === "*") {
    // path filter is *, payload is the value
    count++;
    context.set("count", count);
    return msg;
} else {
    // Safety Check: Ensure payload is an object before trying to traverse it
    if (typeof msg.payload !== 'object' || msg.payload === null) {
        return null; 
    }

    // extract the value from the payload
    const extractedValue = getNestedValue(msg.payload, path);

    if (extractedValue !== undefined) {
        // Standard Dashboard 2.0 Chart format
        msg.payload = extractedValue;
        msg.topic = path; // Useful for identifying the line in the chart
        count++;
        context.set("count", count);
        return msg;
    } else {
        return null; // Don't send anything to the chart if path is invalid
    }
}

