/* 1. Target the outer container to reduce total footprint */
.compact-input.nrdb-ui-text-field {
    height: 34px !important;
    min-height: 34px !important;
    margin-bottom: 2px !important;
}

/* 2. Shrink the actual border/background box (The Boundary) */
.compact-input .v-field {
    --v-field-padding-start: 8px;
    --v-field-padding-end: 8px;
    height: 34px !important;
    min-height: 34px !important;
    border-radius: 4px !important; /* Optional: makes it look tighter */
}

/* 3. Align the text and control the internal height */
.compact-input .v-field__input {
    padding-top: 0 !important;
    padding-bottom: 0 !important;
    min-height: 34px !important;
    height: 34px !important;
    line-height: 34px !important;
    font-size: 0.85rem !important;
}

/* 4. Force the label out of the way or shrink it */
.compact-input .v-field-label {
    font-size: 0.75rem !important;
    top: 50% !important;
    transform: translateY(-50%) !important;
}

/* 5. Eliminate the 'details' slot (extra space at bottom) */
.compact-input .v-input__details {
    display: none !important;
    grid-template-areas: none !important;
    padding: 0 !important;
}

