if (pathFilter === "*") {
    valueToCount = (typeof msg.payload === 'object') ? JSON.stringify(msg.payload) : msg.payload;
} else {
    valueToCount = getNestedValue(msg.payload, pathFilter);
}

// If the attribute doesn't exist, skip
if (valueToCount === undefined) return null;

// 3. Increment Counter
stats[valueToCount] = (stats[valueToCount] || 0) + 1;
